package org.novasos.healthysv2.laboratory;
import static org.novasos.healthysv2.laboratory.LabValues.*;
import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;
@Entity @Table(name="lab_order_item",schema="laboratory") class LabOrderItem{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="lab_order_id",nullable=false)private LabOrder order;@Column(name="lab_exam_catalog_id",nullable=false)private UUID examCatalogId;@Column(columnDefinition="text")private String instructions;@Column(nullable=false,length=30)private String status;@OneToMany(mappedBy="item",cascade=CascadeType.ALL,orphanRemoval=true)private List<Specimen>specimens=new ArrayList<>();protected LabOrderItem(){}static LabOrderItem create(LabOrder order,UUID exam,String instructions){var x=new LabOrderItem();x.id=UUID.randomUUID();x.order=order;x.examCatalogId=Objects.requireNonNull(exam);x.instructions=optional(instructions);x.status="ORDERED";return x;}Specimen collect(String number,String type,Instant at,UUID by){if(Set.of("COMPLETED","CANCELLED").contains(status))throw new IllegalStateException("Item closed");var s=Specimen.create(this,number,type,at,by);specimens.add(s);status="SPECIMEN_COLLECTED";return s;}boolean hasUsableSpecimen(){return specimens.stream().anyMatch(s->Set.of("COLLECTED","RECEIVED").contains(s.getStatus()));}void complete(){status="COMPLETED";}void cancel(){status="CANCELLED";}UUID getId(){return id;}UUID getExamCatalogId(){return examCatalogId;}String getInstructions(){return instructions;}String getStatus(){return status;}List<Specimen>getSpecimens(){return specimens;}}
@Entity @Table(name="specimen",schema="laboratory") class Specimen{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="lab_order_item_id",nullable=false)private LabOrderItem item;@Column(name="specimen_number",nullable=false,unique=true,length=100)private String number;@Column(name="specimen_type",length=100)private String type;@Column(name="collected_at")private Instant collectedAt;@Column(name="collected_by")private UUID collectedBy;@Column(nullable=false,length=30)private String status;protected Specimen(){}static Specimen create(LabOrderItem item,String number,String type,Instant at,UUID by){var x=new Specimen();x.id=UUID.randomUUID();x.item=item;x.number=required(number);x.type=required(type).toUpperCase();x.collectedAt=at==null?Instant.now():at;if(x.collectedAt.isAfter(Instant.now().plusSeconds(60)))throw new IllegalArgumentException("Future collection");x.collectedBy=Objects.requireNonNull(by);x.status="COLLECTED";return x;}void receive(){if(!"COLLECTED".equals(status))throw new IllegalStateException("Specimen is not collected");status="RECEIVED";}void reject(){if(!Set.of("COLLECTED","RECEIVED").contains(status))throw new IllegalStateException("Specimen cannot be rejected");status="REJECTED";}UUID getId(){return id;}String getNumber(){return number;}String getType(){return type;}Instant getCollectedAt(){return collectedAt;}UUID getCollectedBy(){return collectedBy;}String getStatus(){return status;}}
@Entity @Table(name="lab_result",schema="laboratory") class LabResult{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="lab_order_id",nullable=false)private LabOrder order;@Column(name="result_number",nullable=false,unique=true,length=50)private String number;@Column(name="performed_by")private UUID performedBy;@Column(name="validated_by")private UUID validatedBy;@Column(name="performed_at")private Instant performedAt;@Column(name="validated_at")private Instant validatedAt;@Column(nullable=false,length=30)private String status;@Column(columnDefinition="text")private String notes;@OneToMany(mappedBy="result",cascade=CascadeType.ALL,orphanRemoval=true)private List<LabResultItem>items=new ArrayList<>();protected LabResult(){}static LabResult create(LabOrder order,UUID by,Instant at,String notes){var x=new LabResult();x.id=UUID.randomUUID();x.order=order;x.number="RES-"+x.id.toString().replace("-","").substring(0,20).toUpperCase();x.performedBy=Objects.requireNonNull(by);x.performedAt=at==null?Instant.now():at;x.notes=optional(notes);x.status="DRAFT";return x;}LabResultItem addItem(LabOrderItem orderItem,UUID parameterCatalog,String parameter,String value,String unit,BigDecimal min,BigDecimal max,String interpretation,String flag){if(!"DRAFT".equals(status))throw new IllegalStateException("Result is final");var item=LabResultItem.create(this,orderItem,parameterCatalog,parameter,value,unit,min,max,interpretation,flag);items.add(item);return item;}void validate(UUID validator,List<LabOrderItem>ordered){if(!"DRAFT".equals(status))throw new IllegalStateException("Result is final");if(items.isEmpty()||ordered.stream().anyMatch(o->items.stream().noneMatch(i->i.getOrderItemId().equals(o.getId()))))throw new IllegalStateException("Missing result values");validatedBy=Objects.requireNonNull(validator);validatedAt=Instant.now();status="FINAL";}UUID getId(){return id;}String getNumber(){return number;}UUID getPerformedBy(){return performedBy;}UUID getValidatedBy(){return validatedBy;}Instant getPerformedAt(){return performedAt;}Instant getValidatedAt(){return validatedAt;}String getStatus(){return status;}String getNotes(){return notes;}List<LabResultItem>getItems(){return items;}}
@Entity @Table(name="lab_result_item",schema="laboratory") class LabResultItem{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="lab_result_id",nullable=false)private LabResult result;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="lab_order_item_id")private LabOrderItem orderItem;@Column(name="parameter_catalog_id")private UUID parameterCatalogId;@Column(length=255)private String parameter;@Column(length=500)private String value;@Column(length=80)private String unit;@Column(name="reference_min")private BigDecimal referenceMin;@Column(name="reference_max")private BigDecimal referenceMax;@Column(columnDefinition="text")private String interpretation;@Column(name="abnormal_flag",length=30)private String abnormalFlag;protected LabResultItem(){}static LabResultItem create(LabResult result,LabOrderItem orderItem,UUID catalog,String parameter,String value,String unit,BigDecimal min,BigDecimal max,String interpretation,String flag){if(catalog==null&&(parameter==null||parameter.isBlank()))throw new IllegalArgumentException("Parameter required");if(value==null||value.isBlank())throw new IllegalArgumentException("Value required");if(min!=null&&max!=null&&max.compareTo(min)<0)throw new IllegalArgumentException("Invalid reference range");var x=new LabResultItem();x.id=UUID.randomUUID();x.result=result;x.orderItem=Objects.requireNonNull(orderItem);x.parameterCatalogId=catalog;x.parameter=optional(parameter);x.value=value.trim();x.unit=optional(unit);x.referenceMin=min;x.referenceMax=max;x.interpretation=optional(interpretation);x.abnormalFlag=flag==null||flag.isBlank()?"NORMAL":flag.trim().toUpperCase();return x;}UUID getId(){return id;}UUID getOrderItemId(){return orderItem.getId();}UUID getParameterCatalogId(){return parameterCatalogId;}String getParameter(){return parameter;}String getValue(){return value;}String getUnit(){return unit;}BigDecimal getReferenceMin(){return referenceMin;}BigDecimal getReferenceMax(){return referenceMax;}String getInterpretation(){return interpretation;}String getAbnormalFlag(){return abnormalFlag;}}
final class LabValues{private LabValues(){}static String required(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("Required value");return v.trim();}static String optional(String v){return v==null||v.isBlank()?null:v.trim();}}
